#ifndef CUDA_RESULTS_CUH
#define CUDA_RESULTS_CUH

#ifdef __cplusplus
extern "C" {
#endif

typedef struct GPU_results_t GPU_results_t;
typedef struct cuda_info_t cuda_info_t;
typedef struct simulation_configuration_t simulation_configuration_t;


/// @brief Initialize the structure for storing the results of the partial batch generated by each GPU
/// @param nDevices Number of devices
/// @param n Number of neurons
/// @param s Time steps to simulate
/// @param cuda_info Structure with information about how to perform the simulation in the GPU
/// @return Structure for storing results on each GPU
GPU_results_t** initialize_results_str_in_GPU(size_t nDevices, size_t n, cuda_info_t *cuda_info, simulation_configuration_t *conf);

GPU_results_t** initialize_results_str_in_CPU(size_t nDevices, size_t n, cuda_info_t *cuda_info, simulation_configuration_t *conf);


#ifdef __cplusplus
}
#endif

#endif